@Test
public void testSuggestNumFilterBits() {
    // non-positive number distincts
    assertThrows(SketchesArgumentException.class, () -> BloomFilterBuilder.suggestNumFilterBits(0, 0.01));
    // non-positive probability
    assertThrows(SketchesArgumentException.class, () -> BloomFilterBuilder.suggestNumFilterBits(2500, 0.0));
    // probability > 1
    assertThrows(SketchesArgumentException.class, () -> BloomFilterBuilder.suggestNumFilterBits(1000, 2.5));
    // manually computed values based on formula
    assertEquals(BloomFilterBuilder.suggestNumFilterBits(250_000, 0.01), 2396265);
    BloomFilter bf = BloomFilterBuilder.createByAccuracy(250_000, 0.01);
    // next smallest multiple of 64
    assertEquals(bf.getCapacity(), 2396288);
    assertEquals(bf.getNumHashes(), BloomFilterBuilder.suggestNumHashes(250_000, 2396288));
    assertEquals(BloomFilterBuilder.suggestNumFilterBits(5_000_000, 1e-4), 95850584);
    final long seed = 19805243;
    bf = BloomFilterBuilder.createByAccuracy(5_000_000, 1e-4, seed);
    // next smallest multiple of 64
    assertEquals(bf.getCapacity(), 95850624);
    assertEquals(bf.getNumHashes(), BloomFilterBuilder.suggestNumHashes(5_000_000, 95850624));
    assertEquals(bf.getSeed(), seed);
}

@Test(groups = { GENERATE_JAVA_FILES })
public void generatBloomFilterBinariesForCompatibilityTesting() throws IOException {
    final int[] nArr = { 0, 10_000, 2_000_000, 300_000_00 };
    final short[] hArr = { 3, 5 };
    for (final int n : nArr) {
        for (final short numHashes : hArr) {
            // so empty still has valid bit size
            final long configBits = Math.max(n, 1000L);
            final BloomFilter bf = BloomFilterBuilder.createBySize(configBits, numHashes);
            for (int i = 0; i < (n / 10); ++i) {
                bf.update(i);
            }
            if (n > 0) {
                bf.update(Float.NaN);
            }
            assertEquals(bf.isEmpty(), n == 0);
            assertTrue(bf.isEmpty() || (bf.getBitsUsed() > (n / 10)));
            Files.newOutputStream(javaPath.resolve("bf_n" + n + "_h" + numHashes + "_java.sk")).write(bf.toByteArray());
        }
    }
}

@Test(groups = { CHECK_CPP_FILES })
public void readBloomFilterBinariesForCompatibilityTesting() throws IOException {
    final int[] nArr = { 0, 10_000, 2_000_000, 300_000_00 };
    final short[] hArr = { 3, 5 };
    for (final int n : nArr) {
        for (final short numHashes : hArr) {
            final byte[] bytes = Files.readAllBytes(cppPath.resolve("bf_n" + n + "_h" + numHashes + "_cpp.sk"));
            final BloomFilter bf = BloomFilter.heapify(MemorySegment.ofArray(bytes));
            assertEquals(bf.isEmpty(), n == 0);
            assertTrue(bf.isEmpty() || (bf.getBitsUsed() > (n / 10)));
            for (int i = 0; i < (n / 10); ++i) {
                assertTrue(bf.query(i));
            }
            if (n > 0) {
                assert (bf.query(Double.NaN));
            }
        }
    }
}

@Test
public void createNewFilterTest() throws Exception {
    // construct the same filter multiple ways
    final long numItems = 4000;
    final double targetFpp = 0.01;
    final long numBits = BloomFilterBuilder.suggestNumFilterBits(numItems, targetFpp);
    final short numHashes = BloomFilterBuilder.suggestNumHashes(numItems, numBits);
    final int sizeBytes = (int) BloomFilterBuilder.getSerializedFilterSize(numBits);
    final long seed = 89023L;
    final BloomFilter bf1 = new BloomFilter(numBits, numHashes, seed);
    assertTrue(bf1.isEmpty());
    assertFalse(bf1.hasMemorySegment());
    assertFalse(bf1.isOffHeap());
    assertFalse(bf1.isReadOnly());
    try (Arena arena = Arena.ofConfined()) {
        final MemorySegment wseg = arena.allocate(sizeBytes);
        final BloomFilter bf2 = new BloomFilter(numBits, numHashes, seed, wseg);
        assertTrue(bf2.isEmpty());
        assertTrue(bf2.hasMemorySegment());
        assertTrue(bf2.isOffHeap());
        assertFalse(bf2.isReadOnly());
    }
}

