@Test
public void estimationMode() {
    final ItemsSketch<Integer> sketch = new ItemsSketch<>(1 << LG_MIN_MAP_SIZE);
    sketch.update(1, 10);
    sketch.update(2);
    sketch.update(3);
    sketch.update(4);
    sketch.update(5);
    sketch.update(6);
    sketch.update(7, 15);
    sketch.update(8);
    sketch.update(9);
    sketch.update(10);
    sketch.update(11);
    sketch.update(12);
    Assert.assertFalse(sketch.isEmpty());
    Assert.assertEquals(sketch.getStreamLength(), 35);
    {
        final ItemsSketch.Row<Integer>[] items = sketch.getFrequentItems(ErrorType.NO_FALSE_POSITIVES);
        Assert.assertEquals(items.length, 2);
        // only 2 items (1 and 7) should have counts more than 1
        int count = 0;
        for (final ItemsSketch.Row<Integer> item : items) {
            if (item.getLowerBound() > 1) {
                count++;
            }
        }
        Assert.assertEquals(count, 2);
    }
    {
        final ItemsSketch.Row<Integer>[] items = sketch.getFrequentItems(ErrorType.NO_FALSE_NEGATIVES);
        Assert.assertTrue(items.length >= 2);
        // only 2 items (1 and 7) should have counts more than 1
        int count = 0;
        for (final ItemsSketch.Row<Integer> item : items) {
            if (item.getLowerBound() > 5) {
                count++;
            }
        }
        Assert.assertEquals(count, 2);
    }
}

