    out = hash(iArr, 0L);
    Assert.assertEquals(out, out1);
    println(longToHexBytes(out[0]));
    println(longToHexBytes(out[1]));
    println("Longs");
    final long[] lArr = { 0X0807060504030201L, 0X100f0e0d0c0b0a09L, 0X1817161514131211L };
