    n2 = 8;
    basicUnion(n1, n2, lgK1, lgK2, lgMaxK, t1, t2, rt);
    n1 = 8;
    n2 = 8;
    basicUnion(n1, n2, lgK1, lgK2, lgMaxK, t1, t2, rt);
    n1 = 7;
    n2 = 14;
    basicUnion(n1, n2, lgK1, lgK2, lgMaxK, t1, t2, rt);
    println("++END BASE GROUP++");
    int i = 0;
    for (i = 7; i <= 13; i++) {
        lgK1 = i;
        lgK2 = i;
        lgMaxK = i;
        {
            //compute the transition point
            n1 = ((1 << (i - 3)) * 3) / 4;
            n2 = n1;
            basicUnion(n1, n2, lgK1, lgK2, lgMaxK, t1, t2, rt);
            n1 += 2;
            basicUnion(n1, n2, lgK1, lgK2, lgMaxK, t1, t2, rt);
            n1 -= 2;
            n2 += 2;
            basicUnion(n1, n2, lgK1, lgK2, lgMaxK, t1, t2, rt);
            n1 += 2;
            basicUnion(n1, n2, lgK1, lgK2, lgMaxK, t1, t2, rt);
        }
        println("--END MINOR GROUP--");
        lgK1 = i;
        lgK2 = i + 1;
        lgMaxK = i;
        {
            n1 = ((1 << (i - 3)) * 3) / 4;
            n2 = n1;
            basicUnion(n1, n2, lgK1, lgK2, lgMaxK, t1, t2, rt);
            n1 += 2;
            basicUnion(n1, n2, lgK1, lgK2, lgMaxK, t1, t2, rt);
            n1 -= 2;
            n2 += 2;
            basicUnion(n1, n2, lgK1, lgK2, lgMaxK, t1, t2, rt);
            n1 += 2;
            basicUnion(n1, n2, lgK1, lgK2, lgMaxK, t1, t2, rt);
        }
        println("--END MINOR GROUP--");
        lgK1 = i + 1;
        lgK2 = i;
        lgMaxK = i;
        {
            n1 = ((1 << (i - 3)) * 3) / 4;
            n2 = n1;
            basicUnion(n1, n2, lgK1, lgK2, lgMaxK, t1, t2, rt);
            n1 += 2;
            basicUnion(n1, n2, lgK1, lgK2, lgMaxK, t1, t2, rt);
            n1 -= 2;
            n2 += 2;
            basicUnion(n1, n2, lgK1, lgK2, lgMaxK, t1, t2, rt);
            n1 += 2;
            basicUnion(n1, n2, lgK1, lgK2, lgMaxK, t1, t2, rt);
        }
        println("--END MINOR GROUP--");
        lgK1 = i + 1;
        lgK2 = i + 1;
        lgMaxK = i;
        {
            n1 = ((1 << (i - 3)) * 3) / 4;
            n2 = n1;
            basicUnion(n1, n2, lgK1, lgK2, lgMaxK, t1, t2, rt);
            n1 += 2;
            basicUnion(n1, n2, lgK1, lgK2, lgMaxK, t1, t2, rt);
            n1 -= 2;
            n2 += 2;
            basicUnion(n1, n2, lgK1, lgK2, lgMaxK, t1, t2, rt);
            n1 += 2;
            basicUnion(n1, n2, lgK1, lgK2, lgMaxK, t1, t2, rt);
        }
        println("++END MAJOR GROUP++");
    }
