@Test
public void checkCorruptMemorySegmentInput() {
    final HllSketch sk = new HllSketch(12);
    byte[] segObj = sk.toCompactByteArray();
    MemorySegment wseg = MemorySegment.ofArray(segObj);
    HllSketch bad;
    //checkFamily
    try {
        //corrupt, should be 7
        wseg.set(JAVA_BYTE, FAMILY_BYTE, (byte) 0);
        bad = HllSketch.heapify(wseg);
        fail();
    } catch (final SketchesArgumentException e) {
        /* OK */
    }
    //corrected
    insertFamilyId(wseg);
    //check SerVer
    try {
        //corrupt, should be 1
        wseg.set(JAVA_BYTE, SER_VER_BYTE, (byte) 0);
        bad = HllSketch.heapify(wseg);
        fail();
    } catch (final SketchesArgumentException e) {
        /* OK */
    }
    //corrected
    insertSerVer(wseg);
    //check bad PreInts
    try {
        //corrupt, should be 2
        insertPreInts(wseg, 0);
        bad = HllSketch.heapify(wseg);
        fail();
    } catch (final SketchesArgumentException e) {
        /* OK */
    }
    //corrected
    insertPreInts(wseg, 2);
    //check wrong PreInts and LIST
    try {
        //corrupt, should be 2
        insertPreInts(wseg, 3);
        bad = HllSketch.heapify(wseg);
        fail();
    } catch (final SketchesArgumentException e) {
        /* OK */
    }
    //corrected
    insertPreInts(wseg, 2);
    //move to Set mode
    for (int i = 1; i <= 15; i++) {
        sk.update(i);
    }
    segObj = sk.toCompactByteArray();
    wseg = MemorySegment.ofArray(segObj);
    //check wrong PreInts and SET
    try {
        //corrupt, should be 3
        insertPreInts(wseg, 2);
        bad = HllSketch.heapify(wseg);
        fail();
    } catch (final SketchesArgumentException e) {
        /* OK */
    }
    //corrected
    insertPreInts(wseg, 3);
    //move to HLL mode
    for (int i = 15; i <= 1000; i++) {
        sk.update(i);
    }
    segObj = sk.toCompactByteArray();
    wseg = MemorySegment.ofArray(segObj);
    //check wrong PreInts and HLL
    try {
        //corrupt, should be 10
        insertPreInts(wseg, 2);
        bad = HllSketch.heapify(wseg);
        fail();
    } catch (final SketchesArgumentException e) {
        /* OK */
    }
    //corrected
    insertPreInts(wseg, 10);
}

