@Test
public void checkUnionHeapifyRebuildAfterMerge() {
    final int lgK = 12;
    //Build 2 sketches in HLL (dense) mode.
    //(lgK < 8) ? 16 : 1 << (lgK - 3) //allows changing lgK above
    final int u = 1 << (lgK - 3);
    final HllSketch sk1 = new HllSketch(lgK);
    final HllSketch sk2 = new HllSketch(lgK);
    for (int i = 0; i < u; i++) {
        sk1.update(i);
        sk2.update(i + u);
    }
    final int bytes = Union.getMaxSerializationBytes(lgK);
    final MemorySegment wseg = MemorySegment.ofArray(new byte[bytes]);
    //Create original union off-heap
    final Union union1 = new Union(lgK, wseg);
    union1.update(sk1);
    //oooFlag = Rebuild_KxQ = TRUE
    union1.update(sk2);
    assertTrue(!union1.toString().isEmpty());
    boolean rebuild = PreambleUtil.extractRebuildCurMinNumKxQFlag(wseg);
    final double hipAccum = PreambleUtil.extractHipAccum(wseg);
    assertTrue(rebuild);
    assertTrue(hipAccum == 0.0);
    //Heapify byteArr as if it were a sketch, but it is actually a union!
    //rebuilds sk3
    final HllSketch sk3 = HllSketch.heapify(wseg);
    rebuild = sk3.hllSketchImpl.isRebuildCurMinNumKxQFlag();
    assertFalse(rebuild);
}

