    assertEquals(sketch1.getN(), 2 * n);
    assertEquals(sketch1.getMinItem(), Util.longToFixedLengthString(0, digits));
    assertEquals(sketch1.getMaxItem(), Util.longToFixedLengthString((2 * n) - 1, digits));
