@Test
public /**
 * This method emulates an application using an off-heap DoublesSketch that needs to expand off-heap.
 * This demonstrates one example of how to manage a growing off-heap DoublesSketch where the
 * expanded MemorySegments are also off-heap.
 */
void checkMemorySegmentRequestExample() {
    //The default is 128
    final int k = 128;
    //will force requests for more space
    final int itemsIn = 40 * k;
    //Use the custom MemorySegmentRequestExample to do the allocations.
    final MemorySegmentRequestExample mSegReqEx = new MemorySegmentRequestExample();
    //The allocation of the original off-heap MemorySegment for the DoublesSketch
    //Note that this targets the size to only handle 2k values, which is quite small.
    final int initalBytes = DoublesSketch.getUpdatableStorageBytes(k, 2 * k);
    final MemorySegment seg = mSegReqEx.request(initalBytes);
    //Create a new KllLongsSketch and pass the mSegReqEx
    final DoublesSketch sk = DoublesSketch.builder().setK(k).build(seg, mSegReqEx);
    //Update the sketch with way more data than the original MemorySegment can handle, forcing it to request larger MemorySegments.
    for (int n = 1; n <= itemsIn; n++) {
        sk.update(n);
    }
    //Check to make sure the sketch got all the data:
    assertEquals(sk.getMaxItem(), itemsIn);
    assertEquals(sk.getMinItem(), 1);
    assertEquals(sk.getN(), itemsIn);
    //Confirm that the last MemorySegment used by the sketch is, in fact, not the same as the original one that was allocated.
    assertTrue(sk.getMemorySegment() != seg);
    //All done with the sketch. Cleanup any unclosed off-heap MemorySegments.
    mSegReqEx.cleanup();
}

/**
 * Currently, this test only exercises the classic DoublesSketch, but all the quantiles
 * sketches use the same code for getQuantile() and getRank() anyway.
 * This same pattern is also part of the CrossCheckQuantilesTest.
 * This structure of this test allows more detailed analysis for troubleshooting.
 */
@Test
public void checkQuantilesV400() {
    println("org.apache.datasketches.quantiles.CustomQuantilesTest:");
    println("Classic DoubleSketch, Version 4.0.0, k=4, N=12");
    println("");
    //The following for loop creates the following pattern for the sorted view:
    // Quantiles: {10,10,20,20,30,30,40,40}
    // Weights  : { 2, 1, 2, 1, 2, 1, 2, 1}
    //This is easy to create from the classic quantiles sketch directly, but for the other
    //quantiles sketches it is easier to create by loading the sorted view directly via
    //a package-private constructor.
    int k = 4;
    UpdateDoublesSketch sk = DoublesSketch.builder().setK(k).build();
    for (int i = 1; i <= 3; i++) {
        for (int q = 10; q <= k * 10; q += 10) {
            sk.update(q);
        }
    }
    long N = sk.getN();
    DoublesSketchSortedView sv = sk.getSortedView();
    double[] quantilesArr = sv.getQuantiles();
    long[] cumWtsArr = sv.getCumulativeWeights();
    int lenQ = quantilesArr.length;
    println("Sorted View:");
    printf("%13s %13s %13s\n", "QuantilesArr", "CumWtsArr", "NormRanks");
    double normRank;
    for (int i = 0; i < lenQ; i++) {
        normRank = (double) cumWtsArr[i] / N;
        printf("%12.1f%12d%12.4f\n", quantilesArr[i], cumWtsArr[i], normRank);
    }
    println("");
    println("GetRanks, EXCLUSIVE:");
    println("  R of the largest Q at the highest index that is < q. If q <= smallest Q => 0");
    printf("%12s %12s\n", "Quantiles", "NormRanks");
    for (int q = 0; q <= (k * 10) + 5; q += 5) {
        //create a range of quantiles for input
        double normRankEst = sk.getRank(q, EXCLUSIVE);
        double normRankTrue = getTrueDoubleRank(cumWtsArr, quantilesArr, q, EXCLUSIVE);
        assertEquals(normRankEst, normRankTrue);
        printf("%12.1f %12.3f", (double) q, normRankEst);
        if (normRankEst != normRankTrue) {
            println("  " + normRankEst + " != " + normRankTrue);
        } else {
            println("");
        }
    }
    println("");
    println("GetQuantiles, EXCLUSIVE (round down)");
    println("  Q of the smallest rank > r. If r = 1.0 => null or NaN");
    printf("%22s %22s %22s %13s\n", "NormRanksIn", "RawNaturalRank", "TrimmedNatRank", "QuantilesEst");
    long limit = 4 * N;
    double inc = 1.0 / limit;
    for (long j = 0; j <= limit; j++) {
        double normRankIn = (j * inc);
        double qEst = sk.getQuantile(normRankIn, EXCLUSIVE);
        double qTrue = getTrueDoubleQuantile(cumWtsArr, quantilesArr, normRankIn, EXCLUSIVE);
        assertEquals(qEst, qTrue);
        double rawNatRank = normRankIn * N;
        double trimNatRank = getNaturalRank(normRankIn, N, EXCLUSIVE);
        printf("%22.18f %22.18f %22.18f %13.1f", normRankIn, rawNatRank, trimNatRank, qEst);
        if (qEst != qTrue) {
            println("  " + qEst + " != " + qTrue);
        } else {
            println("");
        }
    }
    println("");
    println("GetRanks, INCLUSIVE:");
    println("  R of the largest Q at the highest index that is <= q. If q < smallest Q => 0");
    printf("%12s %12s\n", "Quantiles", "NormRanks");
    for (int q = 0; q <= (k * 10) + 5; q += 5) {
        double nr = sk.getRank(q, INCLUSIVE);
        double nrTrue = getTrueDoubleRank(cumWtsArr, quantilesArr, q, INCLUSIVE);
        assertEquals(nr, nrTrue);
        printf("%12.1f %12.3f", (double) q, nr);
        if (nr != nrTrue) {
            println("  " + nr + " != " + nrTrue);
        } else {
            println("");
        }
    }
    println("");
    println("GetQuantiles, INCLUSIVE (round up)");
    println("  Q of the smallest rank >= r.");
    printf("%22s %22s %22s %13s\n", "NormRanksIn", "RawNaturalRank", "TrimmedNatRank", "QuantilesEst");
    inc = 1.0 / limit;
    for (long j = 0; j <= limit; j++) {
        double normRankIn = (j * inc);
        double qEst = sk.getQuantile(normRankIn, INCLUSIVE);
        double qTrue = getTrueDoubleQuantile(cumWtsArr, quantilesArr, normRankIn, INCLUSIVE);
        assertEquals(qEst, qTrue);
        double rawNatRank = normRankIn * N;
        double trimNatRank = getNaturalRank(normRankIn, N, INCLUSIVE);
        printf("%22.18f %22.18f %22.18f %13.1f", normRankIn, rawNatRank, trimNatRank, qEst);
        if (qEst != qTrue) {
            println("  " + qEst + " != " + qTrue);
        } else {
            println("");
        }
    }
    println("");
}

@Test
public void test() {
    final int n = 70_000;
    final int valueLimit = 1000;
    final int numSketches = 3;
    final int sketchK = 8;
    final int unionK = 8;
    final UpdateDoublesSketch[] sketchArr = new UpdateDoublesSketch[numSketches];
    //builds the input sketches, all on heap
    //make deterministic for test
    DoublesSketch.setRandom(1);
    //holds input values
    final HashSet<Double> set = new HashSet<>();
    for (int s = 0; s < numSketches; s++) {
        sketchArr[s] = buildHeapSketch(sketchK, n, valueLimit, set);
    }
    //loads the on heap union
    //make deterministic for test
    DoublesSketch.setRandom(1);
    final DoublesUnion hUnion = DoublesUnion.builder().setMaxK(unionK).build();
    for (int s = 0; s < numSketches; s++) {
        hUnion.union(sketchArr[s]);
    }
    final DoublesSketch hSketch = hUnion.getResult();
    //loads the direct union
    //make deterministic for test
    DoublesSketch.setRandom(1);
    DoublesUnion dUnion;
    DoublesSketch dSketch;
    try (Arena arena = Arena.ofConfined()) {
        final MemorySegment wseg = arena.allocate(10_000_000);
        dUnion = DoublesUnion.builder().setMaxK(8).build(wseg, null);
        for (int s = 0; s < numSketches; s++) {
            dUnion.union(sketchArr[s]);
        }
        //result is on heap
        dSketch = dUnion.getResult();
    } catch (final Exception e) {
        throw new RuntimeException(e);
    }
    //iterates and counts errors
    final int hCount = hSketch.getNumRetained();
    final int dCount = dSketch.getNumRetained();
    //Retained items must be the same
    assertEquals(hCount, dCount);
    int hErrors = 0;
    int dErrors = 0;
    final QuantilesDoublesSketchIterator hit = hSketch.iterator();
    final QuantilesDoublesSketchIterator dit = dSketch.iterator();
    while (hit.next() && dit.next()) {
        final double v = hit.getQuantile();
        if (!set.contains(v)) {
            hErrors++;
        }
        final double w = dit.getQuantile();
        if (!set.contains(w)) {
            dErrors++;
        }
        //Items must be returned in same order and be equal
        assertEquals(v, w, 0);
    }
    assertTrue(hErrors == 0);
    assertTrue(dErrors == 0);
    println("HeapUnion  : Values: " + hCount + ", errors: " + hErrors);
    //println(hSketch.toString(true, true));
    println("DirectUnion: Values: " + dCount + ", errors: " + dErrors);
    //println(dSketch.toString(true, true));
}

