    for (int i = n; i >= 1; i--) {
        qs1.update(i);
        qs2.update(10 + i);
        qs3.update(i);
    }
    assertEquals(qs1.getQuantile(0.0, EXCLUSIVE), 1.0);
    assertEquals(qs1.getQuantile(0.5, EXCLUSIVE), 5.0);
    assertEquals(qs1.getQuantile(1.0, EXCLUSIVE), 8.0);
