    assertEquals(qs2.getQuantile(1.0, EXCLUSIVE), 18.0);
    assertEquals(qs3.getQuantile(0.0, EXCLUSIVE), 1.0);
    assertEquals(qs3.getQuantile(0.5, EXCLUSIVE), 5.0);
    assertEquals(qs3.getQuantile(1.0, EXCLUSIVE), 8.0);
