@Test
public void checkSimpleFindDouble() {
    final int len = 11;
    final double[] arr = new double[len];
    for (int i = 0; i < len; i++) {
        arr[i] = i;
    }
    int idx;
    for (int i = 0; i < len; i++) {
        idx = BinarySearch.find(arr, 0, len - 1, i);
