/**
 * This is checking the empty, single, exact and estimating cases of an off-heap
 * sketch to make sure they are being stored properly and to check the new capability
 * of calling compact(boolean, MemorySegment) on an already compact sketch. This allows the
 * user to be able to change the order and heap status of an already compact sketch.
 */
@Test
public void checkDirectCompactSketchCompact() {
    MemorySegment wseg1, wseg2;
    CompactSketch csk1, csk2;
    int bytes;
    final int lgK = 6;
    //empty
    final UpdateSketch sk = UpdateSketch.builder().setLogNominalEntries(lgK).build();
    //empty, 8 bytes
    bytes = sk.getCompactBytes();
    wseg1 = MemorySegment.ofArray(new byte[bytes]);
    wseg2 = MemorySegment.ofArray(new byte[bytes]);
    //place into MemorySegment as unordered
    csk1 = sk.compact(false, wseg1);
    assertTrue(csk1 instanceof DirectCompactSketch);
    //empty is always ordered
    assertTrue(csk1.isOrdered());
    //set to unordered again
    csk2 = csk1.compact(false, wseg2);
    assertTrue(csk2 instanceof DirectCompactSketch);
    //empty is always ordered
    assertTrue(csk2.isOrdered());
    //empty has no seed hash
    assertTrue(csk2.getSeedHash() == 0);
    assertEquals(csk2.getCompactBytes(), 8);
    //single
    sk.update(1);
    //single, 16 bytes
    bytes = sk.getCompactBytes();
    wseg1 = MemorySegment.ofArray(new byte[bytes]);
    wseg2 = MemorySegment.ofArray(new byte[bytes]);
    //place into MemorySegment as unordered
    csk1 = sk.compact(false, wseg1);
    assertTrue(csk1 instanceof DirectCompactSketch);
    //single is always ordered
    assertTrue(csk1.isOrdered());
    //set to unordered again
    csk2 = csk1.compact(false, wseg2);
    assertTrue(csk2 instanceof DirectCompactSketch);
    //single is always ordered
    assertTrue(csk2.isOrdered());
    //has a seed hash
    assertTrue(csk2.getSeedHash() != 0);
    assertEquals(csk2.getCompactBytes(), 16);
    //exact
    sk.update(2);
    //exact, 16 bytes preamble, 16 bytes data
    bytes = sk.getCompactBytes();
    wseg1 = MemorySegment.ofArray(new byte[bytes]);
    wseg2 = MemorySegment.ofArray(new byte[bytes]);
    //place into MemorySegment as unordered
    csk1 = sk.compact(false, wseg1);
    assertTrue(csk1 instanceof DirectCompactSketch);
    //should be unordered
    assertFalse(csk1.isOrdered());
    //set to ordered
    csk2 = csk1.compact(true, wseg2);
    assertTrue(csk2 instanceof DirectCompactSketch);
    //should be ordered
    assertTrue(csk2.isOrdered());
    //has a seed hash
    assertTrue(csk2.getSeedHash() != 0);
    assertEquals(csk2.getCompactBytes(), 32);
    //estimating
    final int n = 1 << (lgK + 1);
    for (int i = 2; i < n; i++) {
        sk.update(i);
    }
    //24 bytes preamble + curCount * 8,
    bytes = sk.getCompactBytes();
    wseg1 = MemorySegment.ofArray(new byte[bytes]);
    wseg2 = MemorySegment.ofArray(new byte[bytes]);
    //place into MemorySegment as unordered
    csk1 = sk.compact(false, wseg1);
    assertTrue(csk1 instanceof DirectCompactSketch);
    //should be unordered
    assertFalse(csk1.isOrdered());
    //set to ordered
    csk2 = csk1.compact(true, wseg2);
    assertTrue(csk2 instanceof DirectCompactSketch);
    //should be ordered
    assertTrue(csk2.isOrdered());
    //has a seed hash
    assertTrue(csk2.getSeedHash() != 0);
    final int curCount = csk2.getRetainedEntries();
    assertEquals(csk2.getCompactBytes(), 24 + (curCount * 8));
}

