    assertTrue((entries > k) || (theta2 < theta1), "entries= " + entries + " k= " + k + " theta1= " + theta1 + " theta2= " + theta2);
    sl.shared.rebuild();
    assertEquals(sl.shared.getRetainedEntries(false), k);
    assertEquals(sl.shared.getRetainedEntries(true), k);
    sl.local.rebuild();
    assertEquals(sl.shared.getRetainedEntries(false), k);
    assertEquals(sl.shared.getRetainedEntries(true), k);
}

