        fail("Expected SketchesArgumentException");
    } catch (final SketchesArgumentException e) {
        //Pass
    }
    //fix Family
    seg1.set(JAVA_BYTE, FAMILY_BYTE, (byte) 2);
    //corrupt preLongs
    seg1.set(JAVA_BYTE, PREAMBLE_LONGS_BYTE, (byte) 1);
    try {
        usk2 = DirectQuickSelectSketch.writableWrap(seg1, null, Util.DEFAULT_UPDATE_SEED);
        fail("Expected SketchesArgumentException");
    } catch (final SketchesArgumentException e) {
        //pass
    }
    //fix preLongs
    seg1.set(JAVA_BYTE, PREAMBLE_LONGS_BYTE, (byte) 3);
    //corrupt serVer
    seg1.set(JAVA_BYTE, SER_VER_BYTE, (byte) 2);
    try {
        usk2 = DirectQuickSelectSketch.writableWrap(seg1, null, Util.DEFAULT_UPDATE_SEED);
        fail("Expected SketchesArgumentException");
    } catch (final SketchesArgumentException e) {
        //pass
    }
    //fix serVer
    seg1.set(JAVA_BYTE, SER_VER_BYTE, (byte) 3);
    //corrupt theta and
    seg1.set(JAVA_LONG_UNALIGNED, THETA_LONG, Long.MAX_VALUE >>> 1);
    //corrupt lgArrLongs
    seg1.set(JAVA_BYTE, LG_ARR_LONGS_BYTE, (byte) 10);
    try {
        usk2 = DirectQuickSelectSketch.writableWrap(seg1, null, Util.DEFAULT_UPDATE_SEED);
        fail("Expected SketchesArgumentException");
    } catch (final SketchesArgumentException e) {
        //pass
    }
    //fix theta and
    seg1.set(JAVA_LONG_UNALIGNED, THETA_LONG, Long.MAX_VALUE);
    //fix lgArrLongs
    seg1.set(JAVA_BYTE, LG_ARR_LONGS_BYTE, (byte) 11);
    final byte badFlags = (byte) (COMPACT_FLAG_MASK | READ_ONLY_FLAG_MASK | ORDERED_FLAG_MASK);
    seg1.set(JAVA_BYTE, FLAGS_BYTE, badFlags);
    try {
        usk2 = DirectQuickSelectSketch.writableWrap(seg1, null, Util.DEFAULT_UPDATE_SEED);
        fail("Expected SketchesArgumentException");
    } catch (final SketchesArgumentException e) {
        //pass
    }
    //corrupt length
    final byte[] arr2 = Arrays.copyOfRange(arr1, 0, bytes - 1);
    final MemorySegment seg2 = MemorySegment.ofArray(arr2);
    try {
        usk2 = DirectQuickSelectSketch.writableWrap(seg2, null, Util.DEFAULT_UPDATE_SEED);
        fail("Expected SketchesArgumentException");
    } catch (final SketchesArgumentException e) {
        //pass
    }
}

