    final Union union = SetOperation.builder().setNominalEntries(k).buildUnion(uSeg);
    union.update(1L);
    //#1 double
    union.update(1.5);
    union.update(0.0);
    union.update(-0.0);
    String s = null;
    //null string
    union.update(s);
    s = "";
    //empty string
    union.update(s);
    s = "String";
    //#2 actual string
    union.update(s);
    byte[] byteArr = null;
    //null byte[]
    union.update(byteArr);
    byteArr = new byte[0];
    //empty byte[]
    union.update(byteArr);
    byteArr = "Byte Array".getBytes(UTF_8);
    //#3 actual byte[]
    union.update(byteArr);
    // same as previous
    union.update(ByteBuffer.wrap(byteArr));
    // #4 byte slice
    union.update(ByteBuffer.wrap(byteArr, 0, 4));
    int[] intArr = null;
    //null int[]
    union.update(intArr);
    intArr = new int[0];
    //empty int[]
    union.update(intArr);
    final int[] intArr2 = { 1, 2, 3, 4, 5 };
    //#5 actual int[]
    union.update(intArr2);
    long[] longArr = null;
    //null long[]
    union.update(longArr);
    longArr = new long[0];
    //empty long[]
    union.update(longArr);
    final long[] longArr2 = { 6, 7, 8, 9 };
    //#6 actual long[]
    union.update(longArr2);
