@Test
public void checkPrimitiveUpdates() {
    final int k = 32;
    final Union union = SetOperation.builder().setNominalEntries(k).buildUnion();
    //#1 long
    union.update(1L);
    //#2 double
    union.update(1.5);
    union.update(0.0);
    //#3 double
    union.update(-0.0);
    String s = null;
    //null string
    union.update(s);
    s = "";
    //empty string
    union.update(s);
    s = "String";
    //#4 actual string
    union.update(s);
    byte[] byteArr = null;
    //null byte[]
    union.update(byteArr);
    byteArr = new byte[0];
    //empty byte[]
    union.update(byteArr);
    // empty ByteBuffer
    union.update(ByteBuffer.wrap(byteArr));
    byteArr = "Byte Array".getBytes(UTF_8);
    //#5 actual byte[]
    union.update(byteArr);
    // same as previous
    union.update(ByteBuffer.wrap(byteArr));
    // #6 byte slice
    union.update(ByteBuffer.wrap(byteArr, 0, 4));
    char[] charArr = null;
    //null char[]
    union.update(charArr);
    charArr = new char[0];
    //empty char[]
    union.update(charArr);
    charArr = "String".toCharArray();
    //#7 actual char[]
    union.update(charArr);
    int[] intArr = null;
    //null int[]
    union.update(intArr);
    intArr = new int[0];
    //empty int[]
    union.update(intArr);
    final int[] intArr2 = { 1, 2, 3, 4, 5 };
    //#8 actual int[]
    union.update(intArr2);
    long[] longArr = null;
    //null long[]
    union.update(longArr);
    longArr = new long[0];
    //empty long[]
    union.update(longArr);
    final long[] longArr2 = { 6, 7, 8, 9 };
    //#9 actual long[]
    union.update(longArr2);
    final CompactSketch comp = union.getResult();
    final double est = comp.getEstimate();
    final boolean empty = comp.isEmpty();
    assertEquals(est, 9.0, 0.0);
    assertFalse(empty);
}

