@Test
public void checkGetCurrentBytes() {
    final int k = 64;
    final int lowQSPreLongs = Family.QUICKSELECT.getMinPreLongs();
    final int lowCompPreLongs = Family.COMPACT.getMinPreLongs();
    // QS Sketch
    final UpdateSketch sketch = UpdateSketch.builder().setNominalEntries(k).build();
    assertEquals(sketch.getCurrentPreambleLongs(), lowQSPreLongs);
    //compact form
    assertEquals(sketch.getCompactPreambleLongs(), 1);
    assertEquals(sketch.getCurrentDataLongs(), k * 2);
    assertEquals(sketch.getCurrentBytes(), (k * 2 * 8) + (lowQSPreLongs << 3));
    assertEquals(sketch.getCompactBytes(), lowCompPreLongs << 3);
    final CompactSketch compSk = sketch.compact(false, null);
    assertEquals(compSk.getCompactBytes(), 8);
    assertEquals(compSk.getCurrentBytes(), 8);
    assertEquals(compSk.getCurrentDataLongs(), 0);
    int compPreLongs = computeCompactPreLongs(sketch.isEmpty(), sketch.getRetainedEntries(true), sketch.getThetaLong());
    assertEquals(compPreLongs, 1);
    for (int i = 0; i < k; i++) {
        sketch.update(i);
    }
    assertEquals(sketch.getCurrentPreambleLongs(), lowQSPreLongs);
    //compact form
    assertEquals(sketch.getCompactPreambleLongs(), 2);
    assertEquals(sketch.getCurrentDataLongs(), k * 2);
    assertEquals(sketch.getCurrentBytes(), (k * 2 * 8) + (lowQSPreLongs << 3));
    //compact form  //FAILS HERE
    assertEquals(sketch.getCompactBytes(), (k * 8) + (2 * 8));
    compPreLongs = computeCompactPreLongs(sketch.isEmpty(), sketch.getRetainedEntries(true), sketch.getThetaLong());
    assertEquals(compPreLongs, 2);
    for (int i = k; i < (2 * k); i++) {
        //go estimation mode
        sketch.update(i);
    }
    final int curCount = sketch.getRetainedEntries(true);
    assertEquals(sketch.getCurrentPreambleLongs(), lowQSPreLongs);
    //compact form
    assertEquals(sketch.getCompactPreambleLongs(), 3);
    assertEquals(sketch.getCurrentDataLongs(), k * 2);
    assertEquals(sketch.getCurrentBytes(), (k * 2 * 8) + (lowQSPreLongs << 3));
    //compact form
    assertEquals(sketch.getCompactBytes(), (curCount * 8) + (3 * 8));
    compPreLongs = computeCompactPreLongs(sketch.isEmpty(), sketch.getRetainedEntries(true), sketch.getThetaLong());
    assertEquals(compPreLongs, 3);
    for (int i = 0; i < 3; i++) {
        final int maxCompBytes = Sketch.getMaxCompactSketchBytes(i);
        if (i == 0) {
            assertEquals(maxCompBytes, 8);
        }
        if (i == 1) {
            assertEquals(maxCompBytes, 16);
        }
        //assumes maybe estimation mode
        if (i > 1) {
            assertEquals(maxCompBytes, 24 + (i * 8));
        }
    }
}

