@Test
public void checkMoveAndResizeOffHeap() {
    final int k = 1 << 12;
    final int u = 2 * k;
    final int bytes = Sketch.getMaxUpdateSketchBytes(k);
    MemorySegment skWseg, uWseg;
    try (Arena arena = Arena.ofConfined()) {
        //we never populate the sketch so this size is not relevant
        skWseg = arena.allocate(bytes / 2);
        final UpdateSketch sketch = UpdateSketch.builder().setNominalEntries(k).build(skWseg);
        //The sketch has not changed, so the sketch's internal segment is what we gave it.
        assertTrue(sketch.isSameResource(skWseg));
        //We now do the same with an independent Union
        // way too small, this will forces overflow
        uWseg = arena.allocate(bytes / 2);
        //off-heap union
        final Union union = SetOperation.builder().buildUnion(uWseg);
        //Union has not changed
        assertTrue(union.isSameResource(uWseg));
        //populate first union
        for (int i = 0; i < u; i++) {
            union.update(i);
        }
        //Sketch and Union segments are totally distinct
        assertFalse(union.isSameResource(skWseg));
        //Here the union's segment overflowed and moved to the heap,
        // thus, its reference to its segment is not the one we gave it!
        //moved.
        assertFalse(union.isSameResource(uWseg));
        //Here we create a 2nd Union with a heap segment
        final MemorySegment uWsegHeap = MemorySegment.ofArray(new byte[bytes / 2]);
        //union with on-heap segment
        final Union union2 = SetOperation.builder().buildUnion(uWsegHeap);
        //As before, this establishes that the empty union2 has the same segment that we gave it.
        //Copilot complained this was absent, so here it is!
        assertTrue(union2.isSameResource(uWsegHeap));
        //These two asserts are calling the Interface static method directly and establish
        // what should be obvious, that these are all different segments.
        //obviously not
        assertFalse(MemorySegmentStatus.isSameResource(uWseg, uWsegHeap));
        //tgt moved
        assertFalse(MemorySegmentStatus.isSameResource(uWsegHeap, union.getMemorySegment()));
    }
    //the off-heap segments will be closed here
    //closed as part of the same Arena
    assertFalse(skWseg.scope().isAlive());
    //closed as part of the same Arena
    assertFalse(uWseg.scope().isAlive());
    //we don't need to close the heap segment.
}

