    for (int i = 1; i <= 12; i++) {
        tupleSk.update(i, 1.0);
        thetaSk.update(i + 3);
    }
    //Union
    final Union<DoubleSummary> union = new Union<>(dsso2);
    union.union(tupleSk);
    union.union(thetaSk, ufactory.newSummary().update(1.0));
