    final TupleSketchIterator<DoubleSummary> iiter = icsk.iterator();
    counter = 1;
    while (iiter.next()) {
        final int i = (int) iiter.getSummary().getValue();
        //9 entries = 1
        println(counter++ + ", " + i);
        assertEquals(i, 1);
    }
}

